34: export type InspectionParseResult =
35:   | { ok: true; value: InspectionResultView }
36:   | { ok: false };
37: 
38: function readString(record: Record<string, unknown>, key: string): string | undefined {
39:   const value = record[key];
40:   return typeof value === "string" && value.trim().length > 0 ? value : undefined;
41: }
42: 
43: function normalizeDetail(detail: unknown): InspectionCheckDetail | undefined {
44:   if (detail === undefined || detail === null) return undefined;
45: 
46:   if (typeof detail === "string") {
47:     return detail.trim().length > 0 ? { message: detail, raw: { message: detail } } : undefined;
48:   }
49: 
